mapper.select:
SELECT * FROM frontend_project_probe
WHERE workspace_id = #{workspaceId} AND repo_id = #{repoId}
ORDER BY id DESC
LIMIT #{limit}

SELECT * FROM frontend_project_probe
WHERE status = #{status}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE frontend_project_probe
SET status = #{status},
    version = version + 1
    , modifier_id = #{modifierId}
WHERE id = #{id} AND workspace_id = #{workspaceId} AND version = #{expectedVersion}

mapper.select:
SELECT * FROM frontend_project_probe
WHERE status IN
#{s}
  AND gmt_modified < DATE_SUB(NOW(3), INTERVAL #{beforeMs} / 1000 SECOND)
ORDER BY id ASC
LIMIT #{limit}
